        ) {
            checkMultiplySubtractingAddingConstantA(0.0)
            checkMultiplySubtractingAddingConstantB(0.0)
            checkMultiplySubtractingAddingConstantC(0.0)
        } when: {
            isAmd64 && !isDarwin
